@Override
        protected UniformRandomProvider initialValue() {
            // Create with the default seed generation method
            return source.create();
        }

public static UniformRandomProvider current(RandomSource source) {
        ThreadLocal<UniformRandomProvider> rng = SOURCES.get(source);
        // Implement double-checked locking:
        // https://en.wikipedia.org/wiki/Double-checked_locking#Usage_in_Java
        if (rng == null) {
            // Do the checks on the source here since it is an edge case
            // and the EnumMap handles null (returning null).
            if (source == null) {
                throw new IllegalArgumentException("Random source is null");
            }

            synchronized (SOURCES) {
                rng = SOURCES.get(source);
                if (rng == null) {
                    rng = new ThreadLocalRng(source);
                    SOURCES.put(source, rng);
                }
            }
        }
        return rng.get();
    }

@Override
    public void nextBytes(byte[] bytes) {
        rng.nextBytes(bytes);
    }

@Override
    public void nextBytes(byte[] bytes,
                          int start,
                          int len) {
        final byte[] reduced = new byte[len];
        rng.nextBytes(reduced);
        System.arraycopy(reduced, 0, bytes, start, len);
    }

@Override
    public int nextInt() {
        return rng.nextInt();
    }

@Override
    public int nextInt(int n) {
        return rng.nextInt(n);
    }

@Override
    public long nextLong() {
        return rng.nextLong();
    }

@Override
    public long nextLong(long n) {
        // Code copied from "o.a.c.rng.core.BaseProvider".
        if (n <= 0) {
            throw new IllegalArgumentException("Must be strictly positive: " + n);
        }

        long bits;
        long val;
        do {
            bits = nextLong() >>> 1;
            val  = bits % n;
        } while (bits - val + (n - 1) < 0);

        return val;
    }

@Override
    public boolean nextBoolean() {
        return rng.nextBoolean();
    }

@Override
    public float nextFloat() {
        return rng.nextFloat();
    }

@Override
    public double nextDouble() {
        return rng.nextDouble();
    }

