@Override
        public long sample() {
            // Rejection algorithm copied from o.a.c.rng.core.BaseProvider
            // to avoid the (n <= 0) conditional.
            // See the JDK javadoc for java.util.Random.nextInt(int) for
            // a description of the algorithm.
            long bits;
            long val;
            do {
                bits = rng.nextLong() >>> 1;
                val  = bits % n;
            } while (bits - val + (n - 1) < 0);
            return val;
        }

