@Override
    public SharedStateDiscreteSampler withUniformRandomProvider(UniformRandomProvider rng) {
        return new RejectionInversionZipfSampler(rng, this);
    }

public static SharedStateDiscreteSampler of(UniformRandomProvider rng,
                                                int numberOfElements,
                                                double exponent) {
        return new RejectionInversionZipfSampler(rng, numberOfElements, exponent);
    }

private double hIntegral(final double x) {
        final double logX = Math.log(x);
        return helper2((1 - exponent) * logX) * logX;
    }

private double h(final double x) {
        return Math.exp(-exponent * Math.log(x));
    }

private double hIntegralInverse(final double x) {
        double t = x * (1 - exponent);
        if (t < -1) {
            // Limit value to the range [-1, +inf).
            // t could be smaller than -1 in some rare cases due to numerical errors.
            t = -1;
        }
        return Math.exp(helper1(t) * x);
    }

private static double helper1(final double x) {
        if (Math.abs(x) > TAYLOR_THRESHOLD) {
            return Math.log1p(x) / x;
        } else {
            return 1 - x * (F_1_2 - x * (F_1_3 - F_1_4 * x));
        }
    }

private static double helper2(final double x) {
        if (Math.abs(x) > TAYLOR_THRESHOLD) {
            return Math.expm1(x) / x;
        } else {
            return 1 + x * F_1_2 * (1 + x * F_1_3 * (1 + F_1_4 * x));
        }
    }

