/**
     * Prints a template generators list to stdout.
     */

method_definition:
@Override
    public Void call() throws Exception {
        LogUtils.setLogLevel(reusableOptions.logLevel);
        StressTestDataList list = new StressTestDataList(idPrefix, trials);
        if (providerType == ProviderType.INT) {
            list = list.subsetIntSource();
        } else if (providerType == ProviderType.LONG) {
            list = list.subsetLongSource();
        }
        // Write in one call to the output
        final StringBuilder sb = new StringBuilder();
        switch (listFormat) {
        case PLAIN:
            writePlainData(sb, list);
            break;
        case STRESS_TEST:
        default:
            writeStressTestData(sb, list);
            break;
        }
        // CHECKSTYLE: stop regexp
        System.out.append(sb);
        // CHECKSTYLE: resume regexp
        return null;
    }

static void writePlainData(Appendable appendable,
                               Iterable<StressTestData> testData) throws IOException {
        final String newLine = System.lineSeparator();
        for (final StressTestData data : testData) {
            appendable.append(data.getRandomSource().name());
            if (data.getArgs() != null) {
                appendable.append(' ');
                appendable.append(Arrays.toString(data.getArgs()));
            }
            appendable.append(newLine);
        }
    }

static void writeStressTestData(Appendable appendable,
                                    Iterable<StressTestData> testData) throws IOException {
        // Build the widths for each column
        int idWidth = 0;
        int randomSourceWidth = 15;
        for (final StressTestData data : testData) {
            idWidth = Math.max(idWidth, data.getId().length());
            randomSourceWidth = Math.max(randomSourceWidth, data.getRandomSource().name().length());
        }

        final String newLine = System.lineSeparator();

        appendable.append("# Random generators list.").append(newLine);
        appendable.append("# Any generator with no trials is ignored during testing.").append(newLine);
        appendable.append("#").append(newLine);

        String format = String.format("# %%-%ds   %%-%ds   trials   [constructor arguments ...]%%n",
                idWidth, randomSourceWidth);
        // Do not use try-with-resources or the Formatter will close the Appendable
        // if it implements Closeable. Just flush at the end.
        @SuppressWarnings("resource")
        final Formatter formatter = new Formatter(appendable);
        formatter.format(format, "ID", "RandomSource");
        format = String.format("%%-%ds   %%-%ds   ", idWidth + 2, randomSourceWidth);
        for (final StressTestData data : testData) {
            formatter.format(format, data.getId(), data.getRandomSource().name());
            if (data.getArgs() == null) {
                appendable.append(Integer.toString(data.getTrials()));
            } else {
                formatter.format("%-6d   %s", data.getTrials(), Arrays.toString(data.getArgs()));
            }
            appendable.append(newLine);
        }
        formatter.flush();
    }

static Iterable<StressTestData> readStressTestData(Readable readable) throws IOException {
        final List<StressTestData> list = new ArrayList<>();

        // Validate that all IDs are unique.
        final HashSet<String> ids = new HashSet<>();

        // Do not use try-with-resources as the readable must not be closed
        @SuppressWarnings("resource")
        final Scanner scanner = new Scanner(readable);
        try {
            while (scanner.hasNextLine()) {
                // Expected format:
                //
                //# ID   RandomSource           trials    [constructor arguments ...]
                //12     TWO_CMRES              1
                //13     TWO_CMRES_SELECT       0         [1, 2]
                final String id = scanner.next();
                // Skip empty lines and comments
                if (id.isEmpty() || id.charAt(0) == '#') {
                    scanner.nextLine();
                    continue;
                }
                if (!ids.add(id)) {
                    throw new ApplicationException("Non-unique ID in strest test data: " + id);
                }
                final RandomSource randomSource = RandomSource.valueOf(scanner.next());
                final int trials = scanner.nextInt();
                // The arguments are the rest of the line
                final String arguments = scanner.nextLine().trim();
                final Object[] args = parseArguments(randomSource, arguments);
                list.add(new StressTestData(id, randomSource, args, trials));
            }
        } catch (NoSuchElementException | IllegalArgumentException ex) {
            if (scanner.ioException() != null) {
                throw scanner.ioException();
            }
            throw new ApplicationException("Failed to read stress test data", ex);
        }

        return list;
    }

static Object[] parseArguments(RandomSource randomSource,
                                   String arguments) {
        // Empty string is null arguments
        if (arguments.isEmpty()) {
            return null;
        }

        // Expected format:
        // [data1, data2, ...]
        final int len = arguments.length();
        if (len < 2 || arguments.charAt(0) != '[' || arguments.charAt(len - 1) != ']') {
            throw new ApplicationException("RandomSource arguments should be an [array]: " + arguments);
        }

        // Split the text between the [] on commas
        final String[] tokens = arguments.substring(1, len - 1).split(", *");
        final ArrayList<Object> args = new ArrayList<>();
        for (final String token : tokens) {
            args.add(RNGUtils.parseArgument(token));
        }
        return args.toArray();
    }

static char[] encodeHex(final byte[] data) {
        final int l = data.length;
        final char[] out = new char[l << 1];
        // Two characters form the hex value
        for (int i = 0; i < l; i++) {
            // Upper 4-bits
            out[2 * i]     = HEX_DIGITS[(0xf0 & data[i]) >>> 4];
            // Lower 4-bits
            out[2 * i + 1] = HEX_DIGITS[ 0x0f & data[i]];
        }
        return out;
    }

static byte[] decodeHex(final CharSequence data) {
        final int len = data.length();

        if ((len & 0x01) != 0) {
            throw new IllegalArgumentException("Odd number of characters.");
        }

        final byte[] out = new byte[len >> 1];

        // Two characters form the hex value
        for (int j = 0; j < len; j += 2) {
            final int f = (toDigit(data, j) << 4) |
                           toDigit(data, j + 1);
            out[j / 2] = (byte) f;
        }

        return out;
    }

private static int toDigit(final CharSequence data, final int index) {
        final char ch = data.charAt(index);
        final int digit = Character.digit(ch, 16);
        if (digit == -1) {
            throw new IllegalArgumentException("Illegal hexadecimal character " + ch +
                                               " at index " + index);
        }
        return digit;
    }

String getPrefix() {
            return prefix;
        }

int getLevel() {
            return level;
        }

static void setLogLevel(LogLevel logLevel) {
        LogUtils.logLevel = logLevel;
    }

static boolean isLoggable(LogLevel level) {
        return level.getLevel() <= LogUtils.logLevel.getLevel();
    }

static void debug(String message) {
        if (isLoggable(LogLevel.DEBUG)) {
            println(System.out, LogLevel.DEBUG.getPrefix() + message);
        }
    }

static void debug(String format, Object... args) {
        if (isLoggable(LogLevel.DEBUG)) {
            printf(System.out, LogLevel.DEBUG.getPrefix() + format, args);
        }
    }

static void info(String message) {
        if (isLoggable(LogLevel.INFO)) {
            println(System.out, LogLevel.INFO.getPrefix() + message);
        }
    }

static void info(String format, Object... args) {
        if (isLoggable(LogLevel.INFO)) {
            printf(System.out, LogLevel.INFO.getPrefix() + format, args);
        }
    }

static void error(String message) {
        if (isLoggable(LogLevel.ERROR)) {
            println(System.err, LogLevel.ERROR.getPrefix() + message);
        }
    }

static void error(String format, Object... args) {
        if (isLoggable(LogLevel.ERROR)) {
            printf(System.err, LogLevel.ERROR.getPrefix() + format, args);
        }
    }

static void error(Throwable thrown, String message) {
        if (isLoggable(LogLevel.ERROR)) {
            final StringWriter sw = new StringWriter();
            try (PrintWriter pw = createErrorPrintWriter(sw)) {
                pw.print(message);
                addStackTrace(pw, thrown);
            }
            println(System.err, sw.toString());
        }
    }

static void error(Throwable thrown, String format, Object... args) {
        if (isLoggable(LogLevel.ERROR)) {
            final StringWriter sw = new StringWriter();
            try (PrintWriter pw = createErrorPrintWriter(sw)) {
                pw.printf(format, args);
                addStackTrace(pw, thrown);
            }
            printf(System.err, sw.toString());
        }
    }

private static PrintWriter createErrorPrintWriter(StringWriter sw) {
        final PrintWriter pw = new PrintWriter(sw);
        pw.print(LogLevel.ERROR.getPrefix());
        return pw;
    }

private static void addStackTrace(PrintWriter pw, Throwable thrown) {
        // Complete the current line
        pw.println();
        thrown.printStackTrace(pw);
    }

private static void println(PrintStream out, String message) {
        out.println(message);
    }

private static void printf(PrintStream out, String format, Object... args) {
        // Ensure a new line is added
        out.printf(format + "%n", args);
    }

@Override
    public int compare(CharSequence seq1, CharSequence seq2) {
        // Null is less
        if (seq1 == null) {
            return -1;
        }
        if (seq2 == null) {
            return 1;
        }
        if (seq1.equals(seq2)) {
            return 0;
        }

        int pos1 = 0;
        int pos2 = 0;
        final int length1 = seq1.length();
        final int length2 = seq2.length();

        while (pos1 < length1 && pos2 < length2) {
            final int end1 = nextSubSequenceEnd(seq1, pos1, length1);
            final int end2 = nextSubSequenceEnd(seq2, pos2, length2);

            // If both sub-sequences contain numeric characters, sort them numerically
            int result = 0;
            if (isDigit(seq1.charAt(pos1)) && isDigit(seq2.charAt(pos2))) {
                result = compareNumerically(seq1, pos1, end1, seq2, pos2, end2);
            } else {
                result = compareLexicographically(seq1, pos1, end1, seq2, pos2, end2);
            }

            if (result != 0) {
                return result;
            }

            pos1 = end1;
            pos2 = end2;
        }

        return length1 - length2;
    }

private static int nextSubSequenceEnd(CharSequence seq, int start, int length) {
        int pos = start;
        // Set the sub-sequence type (digits or non-digits)
        final boolean seqType = isDigit(seq.charAt(pos++));
        while (pos < length && seqType == isDigit(seq.charAt(pos))) {
            // Extend the sub-sequence
            pos++;
        }
        return pos;
    }

private static boolean isDigit(char ch) {
        return ch >= 48 && ch <= 57;
    }

private static int compareNumerically(CharSequence seq1, int start1, int end1,
                                          CharSequence seq2, int start2, int end2) {
        // Ignore leading zeros in numbers
        int pos1 = advancePastLeadingZeros(seq1, start1, end1);
        int pos2 = advancePastLeadingZeros(seq2, start2, end2);

        // Simple comparison by length
        final int result = (end1 - pos1) - (end2 - pos2);
        // If equal, the first different number counts.
        if (result == 0) {
            while (pos1 < end1) {
                final char c1 = seq1.charAt(pos1++);
                final char c2 = seq2.charAt(pos2++);
                if (c1 != c2) {
                    return c1 - c2;
                }
            }
        }
        return result;
    }

private static int advancePastLeadingZeros(CharSequence seq, int start, int end) {
        int pos = start;
        // Ignore zeros only when there are further characters
        while (pos < end - 1 && seq.charAt(pos) == '0') {
            pos++;
        }
        return pos;
    }

private static int compareLexicographically(CharSequence seq1, int start1, int end1,
                                                CharSequence seq2, int start2, int end2) {
        final int len1 = end1 - start1;
        final int len2 = end2 - start2;
        final int limit = Math.min(len1, len2);

        for (int i = 0; i < limit; i++) {
            final char c1 = seq1.charAt(i + start1);
            final char c2 = seq2.charAt(i + start2);
            if (c1 != c2) {
                return c1 - c2;
            }
        }
        return len1 - len2;
    }

public static void main(String[] args) {
        // Build the command line manually so we can configure options.
        final CommandLine cmd = new CommandLine(new ExamplesStressCommand())
                .addSubcommand("bridge",  new CommandLine(new BridgeTestCommand())
                                                          .setStopAtPositional(true))
                .addSubcommand("endian",  new EndianessCommand())
                .addSubcommand("list",    new ListCommand())
                .addSubcommand("output",  new CommandLine(new OutputCommand())
                                                          // Allow the input seed using hex (0x, 0X, #)
                                                          // or octal (starting with 0)
                                                          .registerConverter(Long.class, Long::decode))
                .addSubcommand("results", new ResultsCommand())
                .addSubcommand("stress",  new CommandLine(new StressTestCommand())
                                                          .setStopAtPositional(true))
                // Call last to apply to all sub-commands
                .setCaseInsensitiveEnumValuesAllowed(true);

        try {
            // Parse the command line and invokes the Callable program (RNGUtilities)
            cmd.parseWithHandler(new RunLast(), args);
        } catch (final CommandLine.ExecutionException ex) {
            final Throwable cause = ex.getCause();
            if (cause != null) {
                // If this was an exception generated by the application then the full
                // stack trace is not needed depending on log level. This limits stack
                // trace output to unexpected errors in the common use case.
                if (cause instanceof ApplicationException &&
                        !LogUtils.isLoggable(LogUtils.LogLevel.DEBUG)) {
                    LogUtils.error(cause.getMessage());
                } else {
                    LogUtils.error(cause, cause.getMessage());
                }
                System.exit(1);
            }
            // No cause so re-throw. This may be a Picocli parsing error.
            throw ex;
        }
    }

static UniformRandomProvider createReverseBytesProvider(final UniformRandomProvider rng) {
        if (rng instanceof RandomIntSource) {
            return new IntProvider() {
                @Override
                public int next() {
                    return Integer.reverseBytes(rng.nextInt());
                }

                @Override
                public String toString() {
                    return BYTE_REVERSED + rng.toString();
                }
            };
        }
        if (rng instanceof RandomLongSource) {
            return new LongProvider() {
                @Override
                public long next() {
                    return Long.reverseBytes(rng.nextLong());
                }

                @Override
                public String toString() {
                    return BYTE_REVERSED + rng.toString();
                }
            };
        }
        throw new ApplicationException(UNRECOGNISED_NATIVE_TYPE + rng);
    }

